const cfg = $('Config').first().json;

const openedSearch = $('Fetch issues opened').first()?.json ?? {};
const closedSearch = $('Fetch issues closed').first()?.json ?? {};

const isIssue = (item) => item && item.number && !item.pull_request;

const opened = (openedSearch.items ?? []).filter(isIssue);
const closed = (closedSearch.items ?? []).filter(isIssue);
const open = $('Fetch open issues').all().map((i) => i.json).filter(isIssue);
const comments = $('Fetch comments').all().map((i) => i.json).filter((c) => c && c.id);

const TYPES = ['bug', 'task', 'feature', 'needs-triage', 'unlabeled'];

const labelsOf = (issue) =>
  (issue.labels ?? []).map((l) => (typeof l === 'string' ? l : l.name || '').toLowerCase());

const typeOf = (issue) => {
  const labels = labelsOf(issue);
  if (labels.includes('bug')) return 'bug';
  if (labels.includes('feature-request') || labels.includes('feature')) return 'feature';
  if (labels.includes('task')) return 'task';
  if (labels.includes('needs-triage')) return 'needs-triage';
  return 'unlabeled';
};

const emptyCounts = () => Object.fromEntries(TYPES.map((t) => [t, 0]));
const openedByType = emptyCounts();
const closedByType = emptyCounts();
const openByType = emptyCounts();

const bumpType = (bucket, issue) => {
  const type = typeOf(issue);
  bucket[type] += 1;
};
opened.forEach((i) => bumpType(openedByType, i));
closed.forEach((i) => bumpType(closedByType, i));
open.forEach((i) => bumpType(openByType, i));

const authors = new Map();
const authorRow = (login) => {
  const key = login || 'unknown';
  if (!authors.has(key)) {
    authors.set(key, { author: key, opened: 0, closed: 0, open: 0, comments: 0, total: 0 });
  }
  return authors.get(key);
};
const bumpAuthor = (login, field) => {
  const row = authorRow(login);
  row[field] += 1;
  row.total += 1;
};

opened.forEach((i) => bumpAuthor(i.user?.login, 'opened'));
closed.forEach((i) => bumpAuthor(i.user?.login, 'closed'));
open.forEach((i) => bumpAuthor(i.user?.login, 'open'));
comments.forEach((c) => bumpAuthor(c.user?.login, 'comments'));

const byAuthor = [...authors.values()].sort(
  (a, b) => b.total - a.total || a.author.localeCompare(b.author),
);

return [{
  json: {
    week_key: cfg.weekKey,
    week_start: cfg.weekStart,
    week_end: cfg.weekEnd,
    repository: cfg.owner + '/' + cfg.repo,
    generated_at: new Date().toISOString(),
    totals: {
      opened: opened.length,
      closed: closed.length,
      open: open.length,
      comments: comments.length,
    },
    opened_by_type: openedByType,
    closed_by_type: closedByType,
    open_by_type: openByType,
    needs_triage: openedByType['needs-triage'],
    by_author: byAuthor,
  },
}];

const current = $('Build weekly stats').first().json;

// AlwaysOutputData on the Data Table node guarantees at least one item here.
const prevRows = $input.all()
  .map((i) => i.json)
  .filter((row) => row && row.week_key && row.week_key !== current.week_key);

let previous = null;
if (prevRows.length > 0) {
  const row = prevRows[0];
  try {
    previous = typeof row.stats === 'string' ? JSON.parse(row.stats) : row.stats;
  } catch (e) {
    previous = null;
  }
}

const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
const diff = (a, b) => (previous ? num(a) - num(b) : null);

const delta = previous
  ? {
      opened: diff(current.totals.opened, previous.totals?.opened),
      closed: diff(current.totals.closed, previous.totals?.closed),
      open: diff(current.totals.open, previous.totals?.open),
      comments: diff(current.totals.comments, previous.totals?.comments),
      needs_triage: diff(current.needs_triage, previous.needs_triage),
      opened_by_type: Object.fromEntries(
        Object.keys(current.opened_by_type).map((k) => [
          k,
          diff(current.opened_by_type[k], previous.opened_by_type?.[k] ?? 0),
        ]),
      ),
      closed_by_type: Object.fromEntries(
        Object.keys(current.closed_by_type).map((k) => [
          k,
          diff(current.closed_by_type[k], previous.closed_by_type?.[k] ?? 0),
        ]),
      ),
    }
  : null;

const esc = (v) =>
  String(v ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[c]));

const fmt = (v) => (v === null || v === undefined ? '—' : String(v));

const dcell = (v) => {
  if (v === null || v === undefined) {
    return '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right;color:#9ca3af">—</td>';
  }
  const color = v > 0 ? '#0a7d32' : v < 0 ? '#b91c1c' : '#6b7280';
  const sign = v > 0 ? '+' : '';
  return (
    '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right;color:' +
    color +
    ';font-weight:600">' +
    sign +
    v +
    '</td>'
  );
};

const prevTotal = (field) => (previous ? num(previous.totals?.[field]) : null);

const summaryRows = [
  ['Открыто Issues', current.totals.opened, prevTotal('opened'), delta ? delta.opened : null],
  ['Закрыто Issues', current.totals.closed, prevTotal('closed'), delta ? delta.closed : null],
  ['Открыто сейчас (backlog)', current.totals.open, prevTotal('open'), delta ? delta.open : null],
  ['Комментариев за неделю', current.totals.comments, prevTotal('comments'), delta ? delta.comments : null],
  ['Помечено needs-triage', current.needs_triage, previous ? num(previous.needs_triage) : null, delta ? delta.needs_triage : null],
];

const summaryHtml = summaryRows
  .map(
    ([label, cur, prev, d]) =>
      '<tr>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb">' + esc(label) + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right;font-weight:600">' + fmt(cur) + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right;color:#6b7280">' + fmt(prev) + '</td>' +
      dcell(d) +
      '</tr>',
  )
  .join('');

const typeRows = Object.keys(current.opened_by_type)
  .map((type) => {
    const cur = current.opened_by_type[type];
    const prev = previous ? num(previous.opened_by_type?.[type]) : null;
    const d = delta ? delta.opened_by_type[type] : null;
    return (
      '<tr>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb">' + esc(type) + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right">' + cur + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right;color:#6b7280">' + fmt(prev) + '</td>' +
      dcell(d) +
      '</tr>'
    );
  })
  .join('');

const authorRows = current.by_author
  .slice(0, 20)
  .map(
    (a) =>
      '<tr>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb">' + esc(a.author) + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right">' + a.opened + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right">' + a.closed + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right">' + a.open + '</td>' +
      '<td style="padding:6px 10px;border:1px solid #e5e7eb;text-align:right">' + a.comments + '</td>' +
      '</tr>',
  )
  .join('');

const head = (cells) =>
  '<tr>' +
  cells
    .map(
      (c) =>
        '<th style="padding:6px 10px;border:1px solid #e5e7eb;background:#f3f4f6;text-align:left">' +
        c +
        '</th>',
    )
    .join('') +
  '</tr>';

const html_summary =
  '<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;width:100%">' +
  head(['Метрика', 'Эта неделя', 'Прошлая неделя', 'Δ']) +
  summaryHtml +
  '</table>';

const html_types =
  '<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;width:100%">' +
  head(['Тип (открытые Issues)', 'Эта неделя', 'Прошлая неделя', 'Δ']) +
  typeRows +
  '</table>';

const html_authors = current.by_author.length
  ? '<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;width:100%">' +
    head(['Автор', 'Открыл', 'Закрыто', 'Сейчас открыто', 'Комментариев']) +
    authorRows +
    '</table>'
  : '<p style="color:#6b7280">Нет активности авторов за неделю.</p>';

const llm_input = {
  repository: current.repository,
  week_key: current.week_key,
  week_start: current.week_start,
  week_end: current.week_end,
  totals: current.totals,
  opened_by_type: current.opened_by_type,
  closed_by_type: current.closed_by_type,
  open_by_type: current.open_by_type,
  needs_triage: current.needs_triage,
  top_authors: current.by_author.slice(0, 10),
  previous_week: previous
    ? {
        week_key: previous.week_key,
        totals: previous.totals,
        opened_by_type: previous.opened_by_type,
        closed_by_type: previous.closed_by_type,
      }
    : null,
  delta,
};

return [{
  json: {
    ...current,
    stats: current,
    previous_stats: previous,
    delta,
    llm_input,
    html_summary,
    html_types,
    html_authors,
  },
}];

const ctx = $('Compute delta & HTML').first().json;
const llmItem = $input.first().json;
const annotationRaw = llmItem.text ?? llmItem.output ?? llmItem.response ?? '';
const annotation = typeof annotationRaw === 'string' ? annotationRaw : JSON.stringify(annotationRaw, null, 2);

const esc = (v) =>
  String(v ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[c]));

const nl2br = (s) => esc(s).replace(/\n/g, '<br>');
const start = String(ctx.week_start || ctx.week_key || '').slice(0, 10);
const end = String(ctx.week_end || '').slice(0, 10);
const range = start && end ? start + ' — ' + end : String(ctx.week_key || '');

const html =
  '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f9fafb">' +
  '<div style="max-width:900px;margin:0 auto;padding:24px;font-family:Arial,sans-serif;color:#111827">' +
  '<h1 style="font-size:22px;margin:0 0 4px">GitHub Issues: неделя ' + esc(ctx.week_key) + '</h1>' +
  '<p style="margin:0 0 20px;color:#6b7280">Репозиторий ' + esc(ctx.repository) + ' · ' + esc(range) + '</p>' +
  '<h2 style="font-size:17px;margin:24px 0 8px">Сводка</h2>' + ctx.html_summary +
  '<h2 style="font-size:17px;margin:24px 0 8px">По типам</h2>' + ctx.html_types +
  '<h2 style="font-size:17px;margin:24px 0 8px">По авторам</h2>' + ctx.html_authors +
  '<h2 style="font-size:17px;margin:24px 0 8px">AI-комментарий недели</h2>' +
  '<div style="border-left:4px solid #6366f1;background:#eef2ff;padding:12px 16px;border-radius:4px;line-height:1.5">' +
  (annotation.trim() ? nl2br(annotation.trim()) : 'AI-комментарий недоступен.') +
  '</div>' +
  '<p style="margin:24px 0 0;color:#9ca3af;font-size:12px">Отчёт сформирован автоматически n8n. Δ рассчитана по данным Data Table weekly_stats.</p>' +
  '</div></body></html>';

return [{
  json: {
    subject: '[GitHub Issues] Неделя ' + ctx.week_key + ' — ' + ctx.repository,
    html,
  },
}];
